package com.cloudcart.entity;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.*;
public class Entities {private Entities(){}
 public enum Role{USER,ADMIN} public enum OrderStatus{PLACED,PROCESSING,SHIPPED,DELIVERED,CANCELLED}
 @Entity @Table(name="users") public static class User {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@Column(nullable=false) public String name;@Column(nullable=false,unique=true) public String email;@Column(nullable=false) public String password;@Enumerated(EnumType.STRING) public Role role=Role.USER;public Instant createdAt=Instant.now();public User(){} }
 @Entity @Table(name="products") public static class Product {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@Column(nullable=false) public String name;@Column(length=3000) public String description;@Column(nullable=false,precision=12,scale=2) public BigDecimal price;public String category;public String imageUrl;@Column(nullable=false) public int stock;public Instant createdAt=Instant.now();public Product(){} }
 @Entity @Table(name="carts") public static class Cart {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@OneToOne(optional=false) public User user;@OneToMany(mappedBy="cart",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER) public List<CartItem> items=new ArrayList<>();public Cart(){} }
 @Entity @Table(name="cart_items",uniqueConstraints=@UniqueConstraint(columnNames={"cart_id","product_id"})) public static class CartItem {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@ManyToOne(optional=false) public Cart cart;@ManyToOne(optional=false) public Product product;public int quantity;public CartItem(){} }
 @Entity @Table(name="orders") public static class Order {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@ManyToOne(optional=false) public User user;@Enumerated(EnumType.STRING) public OrderStatus status=OrderStatus.PLACED;@Column(nullable=false,precision=12,scale=2) public BigDecimal total=BigDecimal.ZERO;public Instant createdAt=Instant.now();@OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER) public List<OrderItem> items=new ArrayList<>();public Order(){} }
 @Entity @Table(name="order_items") public static class OrderItem {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@ManyToOne(optional=false) public Order order;public Long productId;public String productName;public String imageUrl;@Column(precision=12,scale=2) public BigDecimal price;public int quantity;public OrderItem(){} }
}
